    source:
      '//! Byte-wise compiler support with explicit C linkage and no runtime services.\n\nimport silk.pointer { Pointer }\nimport silk.i32\n\n/// Returns zero for equal byte ranges and a nonzero value for unequal ranges.\n///\n/// # Details\n///\n/// The result has no promised ordering. Zero-length ranges compare equal.\n///\n/// # Gotchas\n///\n/// The caller must provide live readable ranges of `count` bytes.\nexport "C" fn bcmp(left: ?[*]const u8, right: ?[*]const u8, count: usize) -> i32 {\n  if count == 0 { return 0 }\n  unsafe {\n    let first = Intrinsic.pointerRequalify<?[*]const u8, [*]const u8>(left)\n    let second = Intrinsic.pointerRequalify<?[*]const u8, [*]const u8>(right)\n    let mut index: usize = 0\n    while index < count {\n      let a = Pointer.read<u8>(Pointer.at<u8>(first, index))\n      let b = Pointer.read<u8>(Pointer.at<u8>(second, index))\n      if a < b { return -1 }\n      if a > b { return 1 }\n      index = index + 1\n    }\n    return 0\n  }\n}\n',
