    module: 'silk/system_clock',
    path: 'silk/system_clock.silk',
    sourceIdentity: 'silk/system_clock',
    digest: '4242a221b19874a2179c2b50c7587a778af4d273edae2dbcca2b9eebad315ed6',
    documentation: 'silk/system_clock.silk',
    staticInventory: [],
