    namespace: 'TrustAnchor',
    source:
      '//! Owned explicit trust authority with independently configured path and name constraints.\n//!\n//! # When to use\n//!\n//! Use `TrustAnchor.fromCertificate` when a decoded certificate is already explicit authority. Use\n//! `fromCertificateWithConstraints` to attach stricter local path-length or DNS/IP\n//! NameConstraints policy.\n//!\n//! # Details\n//!\n//! A trust anchor owns the complete decoded certificate and any configured constraint DER. The\n//! configured constraints remain distinct from embedded certificate constraints, including when\n//! two anchors contain identical certificate bytes.\n//!\n//! # Gotchas\n//!\n//! Constructing an anchor declares authority; it does not inspect a certificate profile, verify a\n//! self-signature, authenticate a path, or make native trust files equivalent to OS policy.\n\nimport silk.allocator {Allocator, OutOfMemoryError}\nimport silk.bytes {Bytes}\nimport silk.certificate {Certificate}\nimport silk.certificate_profile {\n  CertificateProfile,\n  ProfileClass,\n  ProfileError,\n  ProfileLimits,\n  ProfileOffsetSpace,\n  ProfileReason,\n}\nimport silk.option {Option}\nimport silk.result {Result}\nimport silk.usize\n\n/// One owned trust candidate plus optional locally configured restrictions.\npub struct TrustAnchor {\n  certificateValue: Certificate\n  hasPathLength: bool\n  pathLengthValue: usize\n  hasNameConstraints: bool\n  nameConstraintsValue: Bytes\n  encodedBytesValue: usize\n}\n\nimpl TrustAnchor {\n  /// Moves a decoded certificate into an unconstrained explicit trust anchor without allocating.\n  ///\n  /// # Details\n  ///\n  /// All retained certificate bytes and unsupported extension values remain intact for later\n  /// inspection. Authority does not imply that the certificate is supported by a selected profile.\n  pub fn fromCertificate(certificate: Certificate) -> TrustAnchor {\n    let encoded = Certificate.der(&certificate).length\n    return TrustAnchor {\n      certificateValue: move certificate,\n      hasPathLength: false,\n      pathLengthValue: usize.ZERO,\n      hasNameConstraints: false,\n      nameConstraintsValue: Bytes.make(),\n      encodedBytesValue: encoded,\n    }\n  }\n\n  /// Moves a decoded certificate into explicit authority with independent configured restrictions.\n  ///\n  /// # Details\n  ///\n  /// Configured NameConstraints are validated under the strict DNS/IP subset and copied only after\n  /// validation. The encoded-byte count includes complete certificate DER and configured\n  /// constraint DER. On semantic failure the consumed certificate is dropped. Allocation refusal\n  /// releases partial owned state through ordinary lexical destruction.\n  pub effect fn fromCertificateWithConstraints(\n    certificate: Certificate,\n    maximumPathLength: Option<usize>,\n    configuredNameConstraints: Option<&[u8]>,\n    limits: ProfileLimits,\n  ) -> Result<TrustAnchor, ProfileError>\n  ! OutOfMemoryError\n  ? &mut Allocator {\n    let certificateBytes = Certificate.der(&certificate).length\n    let pathPresent = match & maximumPathLength {\n      Option<usize>.Some {value} => true\n      Option<usize>.None => false\n    }\n    let pathValue = match move maximumPathLength {\n      Option<usize>.Some {value} => value\n      Option<usize>.None => usize.ZERO\n    }\n    return match move configuredNameConstraints {\n      Option<&[u8]>.None => Result.succeed<TrustAnchor, ProfileError>(\n        TrustAnchor {\n          certificateValue: move certificate,\n          hasPathLength: pathPresent,\n          pathLengthValue: pathValue,\n          hasNameConstraints: false,\n          nameConstraintsValue: Bytes.make(),\n          encodedBytesValue: certificateBytes,\n        },\n      )\n      Option<&[u8]>.Some {value} => {\n        let checked = CertificateProfile.validateConfiguredNameConstraints(value, limits)\n        match move checked {\n          Result<(), ProfileError>.Failure {error} => {\n            return Result.failResult<TrustAnchor, ProfileError>(error)\n          }\n          Result<(), ProfileError>.Success {value: ignored} => {}\n        }\n        let total = match move usize.checkedAdd(certificateBytes, value.length) {\n          Option<usize>.Some {value: totalValue} => totalValue\n          Option<usize>.None => {\n            return Result.failResult<TrustAnchor, ProfileError>(\n              ProfileError {\n                kind: ProfileClass.ResourceLimit,\n                reason: ProfileReason.SizeOverflow,\n                extensionIndex: Option.none<usize>(),\n                offsetSpace: ProfileOffsetSpace.ConfiguredConstraintDer,\n                offset: 0,\n              },\n            )\n          }\n        }\n        let copied = run Bytes.copy(value)\n        return Result.succeed<TrustAnchor, ProfileError>(\n          TrustAnchor {\n            certificateValue: move certificate,\n            hasPathLength: pathPresent,\n            pathLengthValue: pathValue,\n            hasNameConstraints: true,\n            nameConstraintsValue: move copied,\n            encodedBytesValue: total,\n          },\n        )\n      }\n    }\n  }\n\n  /// Produces a byte- and constraint-preserving independent owner.\n  ///\n  /// # Details\n  ///\n  /// Allocation refusal releases every partial copy and leaves the original unchanged.\n  pub effect fn clone(self: &Self) -> TrustAnchor ! OutOfMemoryError ? &mut Allocator {\n    let certificate = run Certificate.copy(&self.certificateValue)\n    let constraints = run Bytes.copy(Bytes.asSlice(&self.nameConstraintsValue))\n    return TrustAnchor {\n      certificateValue: move certificate,\n      hasPathLength: self.hasPathLength,\n      pathLengthValue: self.pathLengthValue,\n      hasNameConstraints: self.hasNameConstraints,\n      nameConstraintsValue: move constraints,\n      encodedBytesValue: self.encodedBytesValue,\n    }\n  }\n\n  /// Borrows the complete owned decoded certificate.\n  pub fn certificate(self: &Self) -> &Certificate { return &self.certificateValue }\n\n  /// Returns the independent configured maximum path length when present.\n  pub fn configuredPathLength(self: &Self) -> Option<usize> {\n    if self.hasPathLength { return Option.some<usize>(self.pathLengthValue) }\n    return Option.none<usize>()\n  }\n\n  /// Borrows exact configured NameConstraints DER when present.\n  pub fn configuredNameConstraints(self: &Self) -> Option<&[u8]> {\n    if self.hasNameConstraints {\n      return Option.some<&[u8]>(Bytes.asSlice(&self.nameConstraintsValue))\n    }\n    return Option.none<&[u8]>()\n  }\n\n  /// Returns certificate DER bytes plus configured NameConstraints DER bytes.\n  pub fn encodedBytes(self: &Self) -> usize { return self.encodedBytesValue }\n}\n',
